static const char*LIFE[CL_N][4]={{"С рассвета до заката таскает грузы на набережной ради куска хлеба.","Берётся за любую работу: сегодня на рынке, завтра на стройке.","Привёз в Париж телегу дров и так и осел в квартале.","Живёт в мансарде под самой крышей и знает каждый карниз."},{"Держит маленькую мастерскую на соседней улице и гордится своей работой.","Учит подмастерье ремеслу и жалуется на дороговизну материалов.","Делает вещи, которые покупают даже придворные, но платят с опозданием.","Работает по ночам при свече, чтобы успеть к сроку."},{"Торгует с утра до вечера и знает цену каждому слуху.","Откладывает по монете в старый чулок на чёрный день.","Лавка досталась по наследству и связывает с прошлым.","Все новости квартала сначала попадают к прилавку."},{"Несёт караул и мечтает о пенсии и тихой ферме.","Строг с горожанами, но втайне сочувствует голодным.","Служит Короне, хотя жалованье задерживают уже третий месяц.","Гордится мундиром и начищает сапоги до зеркального блеска."},{"Живёт в роскошном особняке, но средства тают быстрее, чем кажется.","Устраивает салоны и любит слушать чужие секреты.","Тайно читает запрещённые книги философов.","Боится перемен и не доверяет ни слугам, ни друзьям."},{"Служит в приходе и слушает исповеди половины квартала.","Раздаёт хлеб беднякам, хотя церкви самой едва хватает.","Играет по вечерам на старом органе, когда никто не слышит.","Спорит с епископом о бедности и о том, кому служит церковь."},{"Ночует где придётся: то под мостом, то в сарае у рынка.","Знает каждый закоулок и каждую щель в заборе.","Просит милостыню у собора и знает всех прихожан в лицо.","Когда-то жилось лучше, но прошлое лучше не вспоминать."},{"Прислуживает в богатом доме и видит то, что хозяевам лучше скрыть.","Бегает по поручениям с утра до ночи и знает всех торговцев.","Мечтает накопить на лавку и уйти от хозяев.","Тайком читает хозяйские книги, когда никого нет дома."},{"Спорит о правах человека в кофейне до закрытия.","Переписывает бумаги, а по ночам пишет собственные памфлеты.","Лечит бедных бесплатно, потому что так велит совесть.","Учит детей читать и верит, что грамота спасёт мир."},{"Возит грузы по Сене и знает каждую мель.","Перевозит людей с берега на берег и слышит чужие разговоры.","Ловит рыбу на рассвете и продаёт улов у моста.","Копит на собственную лодку и бережёт каждую монету."}};
static const char*WORRY[10]={"Беспокоится из-за дорогого хлеба.","Слышал{|а}, что в Версале собрались Генеральные штаты, и ждёт перемен.","Боится, что город заполнят голодные толпы.","Много слышит о бунтах и ночами не спит.","Надеется, что лето будет урожайным.","Не доверяет слухам, но всё равно их пересказывает.","Опасается новых налогов и сборщиков.","Подолгу слушает ораторов на площади.","Верит, что король справедлив, а лукавят советники.","Мечтает уехать из шумного Парижа."};
static const char*SECRET[10]={"Тайно хранит письма от человека, которому не следует писать.","Прячет под половицей мешочек золота.","Однажды увидел{|а} в подвале то, о чём лучше молчать.","Знает, где спрятан склад оружия, и боится об этом думать.","Давно ищет пропавшего брата.","Тайно помогает беглым крестьянам.","Не умеет читать, но скрывает это от всех.","Носит на шее медальон с портретом, о котором никому не говорит.","Долж{ен|на} крупную сумму ростовщику.","Втайне пишет стихи."};
static const char*RUMOR[CL_N][3]={{"Говорят, хлеб подорожает к осени.","На набережной ищут грузчиков, платят хорошо.","Не лезь на крыши в дождь: черепица скользкая."},{"Для хорошей работы нужны время и терпение.","Заказы идут туго, все ждут перемен.","Ночью на мастерских шалят воры."},{"Торговля стоит: люди боятся тратить деньги.","Лучшие вести узнаёшь у прилавка.","Стража проверяет лавки по утрам."},{"Не носись по улицам, стража такого не любит.","В саду маркиза выставили усиленный пост.","Порядок для всех один."},{"В салонах только и говорят что о Версале.","Мир скоро изменится, и не в нашу пользу.","Не стоит верить газетам."},{"Молитесь о хлебе и о мире.","Колокольню видно на весь квартал.","Двери церкви открыты для всех."},{"Дай монету, и я расскажу, где пройти по крышам.","Стража гоняет нас с площади.","Лучшие сны бывают на сеновале."},{"Мои хозяева скоро уедут из города.","Кучера знают все улицы, но не все крыши.","Лучше не слышать, о чём говорят за столом."},{"Скоро книги будут читать все.","Я пишу памфлет о правах человека.","Свобода начинается с грамоты."},{"Река сегодня высокая.","Мосты держат крепче, чем кажется.","На острове голуби, а собор в тумане."}};
static void bio_fmt(char*dst,int n,const char*src,int female){int j=0;
 for(int i=0;src[i]&&j<n-4;){if(src[i]=='{'){int a=i+1;while(src[i]&&src[i]!='|')i++;if(!src[i])break;int b=i+1;while(src[i]&&src[i]!='}')i++;int ea=b-1,eb=i;int s=female?b:a,e=female?eb:ea;for(int k=s;k<e&&j<n-4;k++)dst[j++]=src[k];if(src[i])i++;}
  else dst[j++]=src[i++];}
 while(j>0&&(dst[j-1]&0xC0)==0x80)j--;if(j>0&&(unsigned char)dst[j-1]>=0xC0)j--; /* не резать букву пополам */
 dst[j]=0;}
static void make_look(Ident*d,int k){Look*l=&d->look;uint32_t h=hs(k,71);
 static const uint32_t SK[6]={RGBX(240,206,176),RGBX(230,190,160),RGBX(216,172,140),RGBX(196,148,116),RGBX(170,120,92),RGBX(236,200,184)};
 static const uint32_t HR[6]={RGBX(50,40,40),RGBX(90,64,44),RGBX(140,104,64),RGBX(30,28,30),RGBX(176,128,70),RGBX(120,56,44)};
 static const uint32_t EY[5]={RGBX(60,90,150),RGBX(80,110,70),RGBX(100,70,50),RGBX(70,70,70),RGBX(120,100,60)};
 l->skin=SK[h%6];if(d->cls==CL_VAGRANT)l->skin=gfx_lerp(l->skin,RGBX(120,90,70),.3f);l->hair=HR[(h>>4)%6];
 if(d->age>56)l->hair=(h&1)?RGBX(214,210,204):RGBX(176,172,168);else if(d->age>44&&(h&2))l->hair=gfx_lerp(l->hair,RGBX(190,186,180),.5f);
 l->eye=EY[(h>>8)%5];l->shoe=RGBX(44,36,32);l->trim=RGBX(240,236,226);l->type=d->female?PT_WOMAN:PT_MAN;l->extra=0;
 static const uint32_t MC[CL_N][4]={{RGBX(112,92,66),RGBX(90,84,70),RGBX(120,104,84),RGBX(100,90,60)},{RGBX(60,80,110),RGBX(80,100,70),RGBX(120,80,60),RGBX(90,70,60)},{RGBX(130,60,60),RGBX(160,120,60),RGBX(70,90,110),RGBX(90,60,90)},{RGBX(52,76,140),RGBX(52,76,140),RGBX(52,76,140),RGBX(52,76,140)},{RGBX(150,60,90),RGBX(60,80,150),RGBX(210,180,70),RGBX(100,140,120)},{RGBX(30,30,34),RGBX(30,30,34),RGBX(36,34,40),RGBX(30,30,34)},{RGBX(90,84,76),RGBX(100,92,80),RGBX(80,76,70),RGBX(96,86,70)},{RGBX(60,90,70),RGBX(110,50,50),RGBX(50,60,90),RGBX(80,70,60)},{RGBX(40,44,60),RGBX(50,50,56),RGBX(60,54,50),RGBX(44,52,60)},{RGBX(50,70,100),RGBX(60,80,90),RGBX(80,70,56),RGBX(70,90,100)}};
 static const uint32_t WC[CL_N][4]={{RGBX(130,100,80),RGBX(100,110,120),RGBX(120,110,90),RGBX(140,110,90)},{RGBX(120,80,100),RGBX(90,110,130),RGBX(130,120,80),RGBX(100,100,110)},{RGBX(150,90,100),RGBX(90,120,140),RGBX(160,130,70),RGBX(120,80,130)},{RGBX(52,76,140),RGBX(52,76,140),RGBX(52,76,140),RGBX(52,76,140)},{RGBX(180,70,110),RGBX(80,110,190),RGBX(220,190,80),RGBX(110,170,150)},{RGBX(28,28,32),RGBX(28,28,32),RGBX(34,32,38),RGBX(28,28,32)},{RGBX(96,88,80),RGBX(86,80,74),RGBX(104,92,76),RGBX(90,84,70)},{RGBX(40,40,46),RGBX(50,50,56),RGBX(36,44,40),RGBX(46,40,50)},{RGBX(70,70,90),RGBX(80,70,80),RGBX(60,80,90),RGBX(90,80,70)},{RGBX(80,100,120),RGBX(100,90,80),RGBX(90,110,100),RGBX(110,100,90)}};
 int ci=(h>>12)%4;l->coat=d->female?WC[d->cls][ci]:MC[d->cls][ci];l->pants=d->female?gfx_lerp(l->coat,RGBX(60,50,56),.25f):RGBX(70+(h>>3)%20,64,60);
 if(d->cls==CL_SOLDIER){l->type=PT_GUARD;l->pants=RGBX(236,236,240);l->trim=RGBX(190,40,50);l->shoe=RGBX(24,24,28);l->extra=(k%3==1)?1:0;return;}
 if(d->cls==CL_SHOP&&!d->female){l->type=PT_MERCH;l->trim=RGBX(236,230,214);}
 if(d->cls==CL_NOBLE){l->extra|=512;l->hair=RGBX(236,232,226);l->trim=RGBX(214,176,70);l->shoe=RGBX(30,26,30);if(!d->female)l->pants=RGBX(236,232,220);}
 if(d->cls==CL_CLERGY){l->trim=RGBX(250,248,248);l->pants=l->coat;if(d->female)l->extra|=1;}
 if(d->cls==CL_SCHOLAR)l->extra|=8;
 if(d->cls==CL_VAGRANT){l->shoe=RGBX(70,56,44);l->pants=RGBX(86,80,72);}
 if(d->cls==CL_SERVANT&&d->female){l->trim=RGBX(250,248,248);l->extra|=1;}
 if(d->female&&d->cls!=CL_NOBLE&&(h&4)==0)l->extra|=1;
 if(!d->female){int v=(d->cls==CL_NOBLE)?0:(d->cls==CL_SAILOR||d->cls==CL_LABOR)?1:(int)((h>>14)%3);l->extra=(l->extra&~(3<<5))|(v<<5);
  if(d->age>24&&d->cls!=CL_NOBLE&&d->cls!=CL_CLERGY&&(h%5<2))l->extra|=1;}
 if(d->age<30&&(h&8))l->extra|=2;if(d->cls==CL_SAILOR&&(h%4==0))l->extra|=16;if(d->age>52)l->extra|=128;if(d->female&&d->cls==CL_NOBLE&&(h%3==0))l->extra|=4;}
static void gen_ids(void){int k=0;
 for(int c=0;c<CL_N;c++)for(int j=0;j<CLN[c];j++,k++){Ident*d=&ids[k];memset(d,0,sizeof *d);uint32_t h=hs(k*7+13,3);d->cls=c;d->female=((h>>3)%1000)<(unsigned)(CLFEM[c]*1000);
  if(c==CL_CLERGY)d->female=(j==2||j==5);if(c==CL_NOBLE)d->female=(j&1);
  d->age=CLAGE[c][0]+(int)((h>>9)%(unsigned)(CLAGE[c][1]-CLAGE[c][0]+1));
  int f=(k*7+3)%40,l=(k*13+5)%60;const char*fn=d->female?NM_F[f]:NM_M[f];
  for(int tries=0;tries<60;tries++){
   if(c==CL_NOBLE){int t=(h>>5)%5;snprintf(d->name,sizeof d->name,"%s %s %s",d->female?NT_F[t]:NT_M[t],fn,NSN[(k*5+j+tries)%16]);}
   else if(c==CL_CLERGY)snprintf(d->name,sizeof d->name,"%s %s %s",d->female?"Сестра":"Отец",fn,SN[l]);
   else snprintf(d->name,sizeof d->name,"%s %s",fn,SN[l]);
   int dup=0;for(int q=0;q<k;q++)if(!strcmp(ids[q].name,d->name))dup=1;if(!dup)break;l=(l+7)%60;}
  snprintf(d->job,sizeof d->job,"%s",d->female?JF[c][j%8]:JM[c][j%9]);
  d->t1=(int)(hs(k,577)%24);d->t2=(int)(hs(k,991)%24);if(d->t2==d->t1||d->t2==(d->t1^1))d->t2=(d->t1+6)%24;}
}
/* особые жители: художник, бегуны Лиги, карманник */
#define NRUN 5
static int painter_id=-1,thief_id=-1,runner_id[NRUN];
static const char*RUN_NICK[NRUN]={"Жак-Трубочист","Лиза-Прачка","Студент Эмиль","Тень","Ворон"};
static void assign_roles(void){
 /* художник — ремесленник, переименовываем занятие */
 painter_id=-1;for(int i=0;i<NID;i++)if(ids[i].cls==CL_ARTISAN&&!ids[i].female&&ids[i].age>40){painter_id=i;break;}
 if(painter_id<0)painter_id=CLN[CL_LABOR];
 Ident*p=&ids[painter_id];snprintf(p->name,sizeof p->name,"Мэтр Огюстен Брюн");snprintf(p->job,sizeof p->job,"художник-портретист");p->role=RO_PAINTER;p->age=58;p->t1=14;p->t2=12;
 /* бегуны Лиги крыш */
 int want[NRUN]={CL_LABOR,CL_LABOR,CL_SCHOLAR,CL_SERVANT,CL_VAGRANT};int wf[NRUN]={0,1,0,1,0};
 for(int r=0;r<NRUN;r++){runner_id[r]=-1;for(int i=0;i<NID;i++){Ident*d=&ids[i];if(d->role||d->cls!=want[r]||d->female!=wf[r]||d->age>34)continue;runner_id[r]=i;break;}
  if(runner_id[r]<0)for(int i=0;i<NID;i++)if(!ids[i].role&&ids[i].cls==want[r]){runner_id[r]=i;break;}
  Ident*d=&ids[runner_id[r]];d->role=RO_RUNNER;if(d->age>30)d->age=19+r*2;
  static const char*RN[NRUN]={"Жак Бодуэн","Лиза Ферран","Эмиль Вернье","Сесиль Дюран","Арман Шове"};snprintf(d->name,sizeof d->name,"%s",RN[r]);}
 for(int i=0;i<NID;i++)if(ids[i].role!=RO_RUNNER&&ids[i].role!=RO_PAINTER)for(int r=0;r<NRUN+1;r++){const char*nm=r<NRUN?ids[runner_id[r]].name:ids[painter_id].name;if(!strcmp(ids[i].name,nm)){char t[112];snprintf(t,sizeof t,"%s-младш%s",ids[i].name,ids[i].female?"ая":"ий");snprintf(ids[i].name,sizeof ids[i].name,"%s",t);}}
 snprintf(ids[runner_id[0]].job,80,"трубочист, бегун Лиги крыш");snprintf(ids[runner_id[1]].job,80,"прачка, бегунья Лиги крыш");snprintf(ids[runner_id[2]].job,80,"студент-медик, бегун Лиги крыш");
 snprintf(ids[runner_id[3]].job,80,"горничная, бегунья Лиги крыш");snprintf(ids[runner_id[4]].job,80,"бывший трубочист, чемпион Лиги крыш");
 thief_id=-1;for(int i=0;i<NID;i++)if(!ids[i].role&&ids[i].cls==CL_VAGRANT&&!ids[i].female){thief_id=i;break;}
 if(thief_id>=0){ids[thief_id].role=RO_THIEF;snprintf(ids[thief_id].job,80,"карманник");ids[thief_id].age=24;}}
static void finish_ids(void){
 for(int k=0;k<NID;k++){Ident*d=&ids[k];uint32_t h=hs(k*7+13,3);int c=d->cls,j=k;char tmp[1600];int n;
  if(d->role==RO_PAINTER)n=snprintf(tmp,sizeof tmp,"Родился в Лионе. Тридцать лет пишет портреты: сначала для знати, теперь для всех, кто согласится посидеть смирно. Задумал «Лица квартала» — сто двадцать восемь портретов всех соседей, от маркиза до нищего. Любопытен, как ребёнок, и щедр до последнего холста.");
  else if(d->role==RO_RUNNER){static const char*RB[NRUN]={"Вырос на крышах: с восьми лет чистил дымоходы и знает каждую трубу квартала. Весёлый и шумный, первым встречает новичков Лиги.","Носит корзины белья с набережной на мансарды и давно поняла, что по крышам быстрее, чем по лестницам. Упряма и не терпит поражений.","Сбегает с лекций, чтобы бегать по карнизам. Считает прыжки по формулам и уверен, что однажды опишет паркур в трактате.","Днём прислуживает в особняке, ночью исчезает по крышам. Говорит мало, двигается бесшумно, за что и получила прозвище.","Бывший трубочист, а ныне чемпион Лиги крыш. Ни разу не проигрывал гонку к собору. Насмешлив и горд, но уважает тех, кто не сдаётся."};
   int r=0;for(int q=0;q<NRUN;q++)if(runner_id[q]==k)r=q;n=snprintf(tmp,sizeof tmp,"Прозвище — «%s». %s %s",RUN_NICK[r],RB[r],QUIRK[d->t1]);}
  else if(d->role==RO_THIEF)n=snprintf(tmp,sizeof tmp,"Родился в предместье Сен-Антуан. Ловок на руку, но не на ноги: стоит его окликнуть, как он бросается бежать по крышам. %s",QUIRK[d->t1]);
  else{uint32_t g=hs(k,1913);n=snprintf(tmp,sizeof tmp,"Родил{ся|ась} %s. %s %s %s",ORIG[(g>>3)%15],LIFE[c][(g>>9)%4],WORRY[(g>>13)%10],QUIRK[d->t1]);if((g>>20)%3==0&&n>0&&n<(int)sizeof tmp)snprintf(tmp+n,sizeof tmp-n," %s",SECRET[(g>>23)%10]);}
  bio_fmt(d->bio,sizeof d->bio,tmp,d->female);make_look(d,k);
  if(d->role==RO_RUNNER){d->look.coat=k==runner_id[4]?RGBX(24,22,28):gfx_lerp(d->look.coat,RGBX(60,60,70),.3f);d->look.trim=RGBX(200,40,48);if(!d->female)d->look.extra=(d->look.extra&~(3<<5))|(1<<5);}
  if(d->role==RO_PAINTER){d->look.coat=RGBX(110,70,90);d->look.extra=(d->look.extra&~(3<<5))|(1<<5)|128;d->look.hair=RGBX(214,210,204);}}}
